ref_postcond:
@icontract.snapshot(lambda arr: arr[:], name="old")
@icontract.ensure(lambda OLD, arr: sorted(arr) == sorted(OLD.old))
@icontract.ensure(lambda arr: all(arr[i] <= arr[i+1] for i in range(len(arr)-1)))
@icontract.ensure(lambda result, arr: result is arr)

postconds:
@icontract.snapshot(lambda arr: sorted(arr[:]), name="sorted_elements")
@icontract.snapshot(lambda arr: len(arr), name="original_length")
@icontract.ensure(lambda arr: all(arr[i] <= arr[i+1] for i in range(len(arr)-1)) if len(arr) > 1 else True, "Array must be sorted in non-decreasing order")
@icontract.ensure(lambda arr, sorted_elements: sorted(arr) == sorted_elements, "Array must contain the same elements as before")
@icontract.ensure(lambda arr, original_length: len(arr) == original_length, "Array length must remain unchanged")

@icontract.snapshot(lambda arr: arr[:], name="arr_before")
@icontract.snapshot(lambda arr: len(arr), name="length_before")
@icontract.snapshot(lambda arr: sorted(arr[:]), name="sorted_before")
@icontract.ensure(lambda arr, length_before: len(arr) == length_before, "Array length must remain the same")
@icontract.ensure(lambda arr, sorted_before: sorted(arr) == sorted_before, "Array must contain the same elements")
@icontract.ensure(lambda arr: all(arr[i] <= arr[i+1] for i in range(len(arr)-1)) if len(arr) > 1 else True, "Array must be sorted in ascending order")

@icontract.snapshot(lambda arr: list(arr), name="original_arr")
@icontract.ensure(lambda arr: all(arr[i] <= arr[i+1] for i in range(len(arr)-1)) if len(arr) > 1 else True, "Array must be sorted in non-decreasing order")
@icontract.ensure(lambda arr, original_arr: len(arr) == len(original_arr), "Array length must be preserved")
@icontract.ensure(lambda arr, original_arr: sorted(arr) == sorted(original_arr), "Array must contain same elements as original")

@icontract.snapshot(lambda arr: arr[:], name="old_arr")
@icontract.ensure(lambda arr, old_arr: len(arr) == len(old_arr), "Length must be preserved")
@icontract.ensure(lambda arr, old_arr: sorted(arr) == sorted(old_arr), "Must contain same elements as input")
@icontract.ensure(lambda arr: len(arr) <= 1 or all(arr[i] <= arr[i+1] for i in range(len(arr)-1)), "Array must be sorted in non-decreasing order")

@icontract.snapshot(lambda arr: list(arr), name="original_arr")
@icontract.snapshot(lambda arr: len(arr), name="original_length")
@icontract.snapshot(lambda arr: sorted(arr), name="sorted_original")
@icontract.ensure(lambda arr, original_length: len(arr) == original_length, "Array length must be preserved")
@icontract.ensure(lambda arr: all(arr[i] <= arr[i + 1] for i in range(len(arr) - 1)) if len(arr) > 1 else True, "Array must be sorted in non-decreasing order")
@icontract.ensure(lambda arr, sorted_original: sorted(arr) == sorted_original, "Array must contain the same elements as the original (permutation)")
